import React, { useCallback, useMemo, useRef, useState, type ComponentRef } from 'react';
import { Linking, RefreshControl, ScrollView, Text, useWindowDimensions, View } from 'react-native';
import { router, useFocusEffect } from 'expo-router';
import { EventMap } from '../../components/event-map';
import { ListToolbar, MenuActionItem, MenuCheckItem, Popover, useListChrome } from '../../components/list-menu';
import { Button, EmptyState, ErrorText, ListView, Page, PageHeader, Segmented, styles } from '../../components/ui';
import { EventRow, useEventListLayout } from '../../components/events';
import { EVENTS_PAST_DAYS, listEvents, listMemberEventLinks, syncMeetupEvents, type MemberEventLinks } from '../../lib/api';
import { PRODUCT_NAME } from '../../lib/config';
import { readDeviceLocation } from '../../lib/device-location';
import { DEFAULT_NEAR_RADIUS, NEAR_RADII, type GeoPoint, type NearRadius } from '../../lib/event-filters';
import { groupMapMarkers, markersForEvents } from '../../lib/event-map';
import { classifyEventRelation } from '../../lib/event-relation';
import { eventInMemberDirectory } from '../../lib/event-visibility';
import {
  EVENT_VIEWS, eventScreenActions, eventViewLabel, eventViewSpec, eventsForView, memberEventBadge,
  type EventViewId,
} from '../../lib/event-views';
import { fmtWhen } from '../../lib/format';
import { useSession } from '../../lib/session';
import type { ClubEvent } from '../../lib/types';
import { fs } from '../../lib/theme';

const EMPTY_LINKS: MemberEventLinks = { attendingIds: [], hostedMeetupIds: [] };

export default function Events() {
  const { userId, isModerator, demo } = useSession();
  const mod = isModerator && !demo && !!userId;
  const actions = eventScreenActions(mod);
  const [events, setEvents] = useState<ClubEvent[] | null>(null);
  const [links, setLinks] = useState<MemberEventLinks>(EMPTY_LINKS);
  const [refreshing, setRefreshing] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [view, setView] = useState<EventViewId>('mine');
  const { query: q, setQuery: setQ, searchOpen, menu, anchor, viewBtn, moreBtn, searchRef, closeMenu, openMenu, toggleSearch } = useListChrome();
  const [syncing, setSyncing] = useState(false);
  const [syncNote, setSyncNote] = useState<string | null>(null);
  const [radius, setRadius] = useState<NearRadius>(DEFAULT_NEAR_RADIUS);
  const [point, setPoint] = useState<GeoPoint | null>(null);
  const [locStatus, setLocStatus] = useState<'idle' | 'loading' | 'ready' | 'denied' | 'unavailable'>('idle');
  const nearReq = useRef(0);
  const scrollRef = useRef<ComponentRef<typeof ScrollView>>(null);

  const load = useCallback(async () => {
    setRefreshing(true);
    try {
      const [rows, rel] = await Promise.all([
        listEvents(),
        userId ? listMemberEventLinks(userId) : Promise.resolve(EMPTY_LINKS),
      ]);
      setEvents(rows);
      setLinks(rel);
      setErr(null);
    } catch (e: any) { setErr(e.message); }
    finally { setRefreshing(false); }
  }, [userId]);
  useFocusEffect(useCallback(() => { if (userId) load(); }, [userId, load]));

  const sync = async () => {
    setSyncing(true); setSyncNote(null); setErr(null);
    try {
      const r = await syncMeetupEvents();
      const created = r.created ? ` ${r.created} new club event${r.created === 1 ? '' : 's'}.` : '';
      setSyncNote(`Synced ${r.upserted} Meetup listings.${created}`);
      await load();
    } catch (e: any) { setErr(e.message); }
    finally { setSyncing(false); }
  };

  // Location is requested only when the Near Me view is opened.
  const requestNear = useCallback(() => {
    if (point) {
      setLocStatus('ready');
      return;
    }
    const req = ++nearReq.current;
    setLocStatus('loading');
    readDeviceLocation().then((res) => {
      if (nearReq.current !== req) return;
      if (res.ok) {
        setPoint(res.point);
        setLocStatus('ready');
      } else {
        setPoint(null);
        setLocStatus(res.reason);
      }
    });
  }, [point]);

  const relation = useMemo(() => ({
    userId,
    attendingIds: new Set(links.attendingIds),
    hostedMeetupIds: new Set(links.hostedMeetupIds),
  }), [userId, links]);
  const spec = eventViewSpec(view);
  const nearActive = spec.near && locStatus === 'ready' && point != null;
  const rows = useMemo(() => {
    if (!events) return null;
    const listed = events.filter((event) => eventInMemberDirectory(event, { moderator: mod, userId, attendingIds: relation.attendingIds }));
    return eventsForView(listed, {
      view,
      query: q,
      now: Date.now(),
      relation,
      near: nearActive && point ? { origin: point, radiusMiles: radius } : null,
    });
  }, [events, view, q, relation, nearActive, point, radius, mod, userId]);
  const mapped = useMemo(() => (rows ? markersForEvents(rows, (e) => fmtWhen(e.starts_at)) : null), [rows]);
  const numberedPins = useMemo(
    () => (mapped ? groupMapMarkers(mapped.markers).some((group) => group.length > 1) : false),
    [mapped],
  );
  const { columns, onLayout } = useEventListLayout();
  const { height: windowHeight } = useWindowDimensions();
  const mapHeight = Math.max(340, Math.min(640, Math.round(windowHeight * 0.58)));
  const showMap = spec.map && (mapped?.markers.length ?? 0) > 0;
  const openEvent = useCallback((id: string) => { router.push(`/events/${id}`); }, []);
  const setPageScroll = useCallback((enabled: boolean) => {
    const node = scrollRef.current as { setNativeProps?: (props: { scrollEnabled: boolean }) => void } | null;
    try { node?.setNativeProps?.({ scrollEnabled: enabled }); } catch { /* The web scroll view has nothing to freeze. */ }
  }, []);
  const onMapLock = useCallback((locked: boolean) => { setPageScroll(!locked); }, [setPageScroll]);

  const chooseView = (next: EventViewId) => {
    closeMenu();
    setView(next);
    if (next !== 'map') setPageScroll(true);
    if (next === 'near') requestNear();
  };

  const past = spec.range === 'past';
  const searching = q.trim().length > 0;
  const nearHint = !spec.near ? null
    : locStatus === 'loading' || locStatus === 'idle' ? 'Finding your location…'
      : locStatus === 'denied' ? 'Location is off, so Near me is not filtering. Allow location access and try again.'
        : locStatus === 'unavailable' ? 'Location is not available here, so Near me is not filtering.'
          : locStatus === 'ready' ? `Within ${radius} miles, using the city on each event. Online events stay listed.`
            : null;
  const emptyTitle = searching ? 'No events'
    : view === 'past' ? 'No past events'
      : view === 'near' ? 'No events nearby'
        : view === 'online' ? 'No online events'
          : view === 'in_person' ? 'No in-person events'
            : view === 'hybrid' ? 'No hybrid events'
              : 'No upcoming events';
  const emptyBody = searching ? 'Nothing matches your search.'
    : view === 'mine' ? 'Events you are hosting or going to show up here.'
      : view === 'past' ? `Events from the last ${EVENTS_PAST_DAYS} days show up here.`
        : view === 'near' ? 'Nothing upcoming is within this distance. Online events stay listed when location is on.'
          : view === 'online' ? 'Upcoming online events show up here.'
            : view === 'in_person' ? 'Upcoming in-person events show up here.'
              : view === 'hybrid' ? 'Upcoming hybrid events show up here.'
                : `Events on ${PRODUCT_NAME} show up here.`;
  const showClubEmptyAction = !searching && (view === 'upcoming' || view === 'map' || (view === 'mine' && mod));

  return (
    <Page scrollRef={scrollRef} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => load()} />}>
      <PageHeader icon="calendar" title="Events" />
      <ErrorText>{err}</ErrorText>
      {syncNote ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{syncNote}</Text> : null}
      <View style={{ gap: 8 }}>
        <ListToolbar
          menuLabel={eventViewLabel(view)} menuExpanded={menu === 'views'} onPressMenu={() => openMenu('views')} menuButtonRef={viewBtn}
          searchOpen={searchOpen} onToggleSearch={toggleSearch} searchLabel="Search events" query={q} onQuery={setQ}
          searchPlaceholder="Search events…" searchInputRef={searchRef}
          showMore={actions.length > 0} moreExpanded={menu === 'more'} onPressMore={() => openMenu('more')} moreButtonRef={moreBtn}
        />
        {past ? <Text style={[styles.muted, { fontSize: fs(12) }]}>Last {EVENTS_PAST_DAYS} days.</Text> : null}
        {spec.near && locStatus === 'ready' ? (
          <Segmented<NearRadius> value={radius} onChange={setRadius} options={NEAR_RADII.map((miles) => ({ value: miles, label: `${miles} mi` }))} />
        ) : null}
        {nearHint ? <Text style={[styles.muted, { fontSize: fs(12) }]}>{nearHint}</Text> : null}
      </View>
      <View onLayout={onLayout} style={{ gap: 10 }}>
        {!events && !err ? <ListView loading /> : null}
        {rows && !showMap && rows.length === 0 ? (
          <ListView empty={<EmptyState icon="calendar-outline" title={emptyTitle} body={emptyBody}
            action={showClubEmptyAction ? (mod
              ? <Button small icon="add" title="New event" onPress={() => router.push('/events/manage/new')} />
              : view === 'mine' ? undefined
                : <Button small variant="neutral" icon="open-outline" title="Find us on Meetup" onPress={() => Linking.openURL('https://www.meetup.com/reading-philosophy/')} />)
              : undefined} />} />
        ) : null}
        {spec.map && mapped && mapped.markers.length === 0 && rows && rows.length > 0 ? (
          <Text style={[styles.muted, { fontSize: fs(12) }]}>Nothing to place on the map. Online events, and events with no known city, stay in the list.</Text>
        ) : null}
        {showMap && mapped ? (
          <>
            <EventMap markers={mapped.markers} height={mapHeight} onOpen={openEvent} onLock={onMapLock} />
            <Text style={[styles.muted, { fontSize: fs(12) }]}>
              Pins mark the city center. Map data © OpenStreetMap contributors, tiles by OpenFreeMap.
              {numberedPins ? ' Tap a numbered pin to choose an event.' : ''}
            </Text>
            {mapped.unplaced.length > 0 ? (
              <ListView title="Not on the map" note="Online, or no known city." count={mapped.unplaced.length} columns={columns}>
                {mapped.unplaced.map((e) => <EventRow key={e.id} e={e} past={past} mod={mod} columns={columns} badge={memberEventBadge(classifyEventRelation(e, relation))} />)}
              </ListView>
            ) : null}
          </>
        ) : null}
        {rows && !showMap && rows.length > 0 ? (
          <ListView columns={columns}>
            {rows.map((e) => <EventRow key={e.id} e={e} past={past} mod={mod} columns={columns} badge={memberEventBadge(classifyEventRelation(e, relation))} />)}
          </ListView>
        ) : null}
      </View>
      <Popover visible={menu === 'views'} anchor={anchor} align="left" width={280} onClose={closeMenu}>
        {EVENT_VIEWS.map((option) => (
          <MenuCheckItem key={option.id} label={option.label} selected={option.id === view} onPress={() => chooseView(option.id)} />
        ))}
      </Popover>
      <Popover visible={menu === 'more'} anchor={anchor} align="right" width={220} onClose={closeMenu}>
        {actions.includes('sync') ? (
          <MenuActionItem icon="sync" label={syncing ? 'Syncing…' : 'Sync Meetup'} disabled={syncing} onPress={() => { closeMenu(); sync(); }} />
        ) : null}
        {actions.includes('new') ? (
          <MenuActionItem icon="add" label="New event" onPress={() => { closeMenu(); router.push('/events/manage/new'); }} />
        ) : null}
      </Popover>
    </Page>
  );
}
