// Map page shared by the native WebView and the web iframe.
// Tiles are OpenFreeMap (OpenStreetMap data). No Google Maps, no API key.

import { groupMapMarkers, type MapMarker } from './event-map';

const MAP_STYLE = 'https://tiles.openfreemap.org/styles/positron';
const MAPLIBRE_JS = 'https://cdn.jsdelivr.net/npm/maplibre-gl@5.6.1/dist/maplibre-gl.js';
const MAPLIBRE_CSS = 'https://cdn.jsdelivr.net/npm/maplibre-gl@5.6.1/dist/maplibre-gl.css';

/** Self-contained map page. Marker text is JSON, not interpolated HTML. */
export function buildEventMapHtml(markers: readonly MapMarker[]): string {
  const groups = groupMapMarkers(markers).map((events) => ({
    lat: events[0].lat,
    lng: events[0].lng,
    events: events.map((event) => ({
      id: event.id,
      title: event.title,
      whenLabel: event.whenLabel,
      city: event.city,
    })),
  }));
  const data = JSON.stringify(groups).replace(/</g, '\\u003c');
  return `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
<link rel="stylesheet" href="${MAPLIBRE_CSS}">
<style>
  html, body, #map { margin: 0; height: 100%; width: 100%; background: #e8e4dc; }
  #map { touch-action: none; }
  .pin {
    box-sizing: border-box; width: 36px; height: 36px; border-radius: 18px;
    border: 2px solid #fff; background: #1c3d6e; color: #fff;
    font: 600 14px/32px sans-serif; text-align: center; padding: 0; cursor: pointer;
    box-shadow: 0 1px 3px rgba(18, 41, 75, 0.45);
  }
  .choices { max-height: 220px; overflow: auto; }
  .choice {
    display: block; width: 100%; text-align: left; background: #fff; border: 0;
    border-bottom: 1px solid #e6e0d4; padding: 10px 12px; cursor: pointer;
    font: 600 15px/1.3 sans-serif; color: #1d2433;
  }
  .choice small { display: block; margin-top: 2px; font-weight: 400; font-size: 12px; color: #5b6475; }
  .choice:active { background: #f6f2ea; }
  .maplibregl-popup-content { padding: 0; border-radius: 8px; overflow: hidden; }
</style>
</head>
<body>
<div id="map"></div>
<script type="application/json" id="pins">${data}</script>
<script src="${MAPLIBRE_JS}"></script>
<script>
(function () {
  function post(msg) {
    var data = JSON.stringify(msg);
    if (window.ReactNativeWebView && window.ReactNativeWebView.postMessage) window.ReactNativeWebView.postMessage(data);
    else if (window.parent && window.parent !== window) window.parent.postMessage(data, '*');
  }
  var mapEl = document.getElementById('map');
  mapEl.addEventListener('pointerdown', function () { post({ type: 'lock' }); });
  window.addEventListener('pointerup', function () { post({ type: 'unlock' }); });
  window.addEventListener('pointercancel', function () { post({ type: 'unlock' }); });
  document.addEventListener('click', function (event) {
    var node = event.target;
    while (node && node !== document.body) {
      if (node.tagName === 'A' && node.href) {
        event.preventDefault();
        post({ type: 'link', url: node.href });
        return;
      }
      node = node.parentNode;
    }
  }, true);
  if (typeof maplibregl === 'undefined') { post({ type: 'error' }); return; }
  var groups = [];
  try { groups = JSON.parse(document.getElementById('pins').textContent || '[]'); }
  catch (err) { post({ type: 'error' }); return; }
  if (!groups.length) return;
  var ready = false;
  var map;
  try {
    map = new maplibregl.Map({
      container: 'map',
      style: ${JSON.stringify(MAP_STYLE)},
      center: [groups[0].lng, groups[0].lat],
      zoom: 10,
      minZoom: 4,
      maxZoom: 12,
      attributionControl: true,
      dragRotate: false,
      pitchWithRotate: false,
      fadeDuration: 0
    });
  } catch (err) {
    post({ type: 'error' });
    return;
  }
  map.touchZoomRotate.disableRotation();
  map.addControl(new maplibregl.NavigationControl({ showCompass: false, visualizePitch: false }), 'top-right');
  map.on('error', function (e) {
    if (ready) return;
    var message = String((e && e.error && e.error.message) || '');
    if (/WebGL|Failed to initialize/i.test(message)) post({ type: 'error' });
  });
  function place() {
    var bounds = new maplibregl.LngLatBounds();
    var popup = null;
    groups.forEach(function (group) {
      bounds.extend([group.lng, group.lat]);
      var events = group.events || [];
      var el = document.createElement('button');
      el.type = 'button';
      el.className = 'pin';
      if (events.length > 1) el.textContent = String(events.length);
      var city = (events[0] && events[0].city) || '';
      el.setAttribute('aria-label', events.length === 1 ? (events[0].title || 'Event') : (events.length + ' events' + (city ? ' in ' + city : '')));
      el.addEventListener('click', function (click) {
        click.preventDefault();
        click.stopPropagation();
        if (events.length === 1) {
          post({ type: 'open', id: events[0].id });
          return;
        }
        if (popup) popup.remove();
        var box = document.createElement('div');
        box.className = 'choices';
        events.forEach(function (event) {
          var button = document.createElement('button');
          button.type = 'button';
          button.className = 'choice';
          var name = document.createElement('span');
          name.textContent = event.title || 'Event';
          var meta = document.createElement('small');
          meta.textContent = event.city ? (event.whenLabel + ' · ' + event.city) : (event.whenLabel || '');
          button.appendChild(name);
          button.appendChild(meta);
          button.addEventListener('click', function (choice) {
            choice.preventDefault();
            choice.stopPropagation();
            post({ type: 'open', id: event.id });
          });
          box.appendChild(button);
        });
        popup = new maplibregl.Popup({ offset: 22, closeButton: true, closeOnMove: false, maxWidth: '280px' })
          .setLngLat([group.lng, group.lat])
          .setDOMContent(box)
          .addTo(map);
      });
      new maplibregl.Marker({ element: el, anchor: 'center' }).setLngLat([group.lng, group.lat]).addTo(map);
    });
    if (groups.length === 1) map.jumpTo({ center: [groups[0].lng, groups[0].lat], zoom: 11 });
    else map.fitBounds(bounds, { padding: 48, maxZoom: 11, duration: 0 });
  }
  map.on('load', function () { ready = true; place(); });
})();
</script>
</body>
</html>`;
}
