// Pins for the Events map. Same city centroids as Near me. A street is never a pin.
// Online events stay off the map even when a city is stored on the row.

import { classifyEventFormat, eventDistancePoint, type EventFormatInput, type GeoPoint } from './event-filters';
import { publicLocality } from './place';

export type MapMarker = {
  id: string;
  title: string;
  whenLabel: string;
  city: string;
  lat: number;
  lng: number;
};

export type MapMessage =
  | { type: 'open'; id: string }
  | { type: 'link'; url: string }
  | { type: 'lock' }
  | { type: 'unlock' }
  | { type: 'error' };

const LINK_SUFFIXES = ['openstreetmap.org', 'openfreemap.org', 'openmaptiles.org', 'maplibre.org'];

/** City centroid for a pin. Null for online events and for places we cannot locate by city. */
export function eventMapPoint(event: EventFormatInput): GeoPoint | null {
  if (classifyEventFormat(event) === 'online') return null;
  return eventDistancePoint(event);
}

/** City label for a pin. Null when the event is not on the map. Never a street. */
export function eventMapCity(event: EventFormatInput): string | null {
  if (!eventMapPoint(event)) return null;
  return publicLocality(event.venue_locality) ?? publicLocality(event.venue_address);
}

export function markersForEvents<T extends EventFormatInput & { id: string; title: string }>(
  events: readonly T[],
  whenLabel: (event: T) => string,
): { markers: MapMarker[]; unplaced: T[] } {
  const markers: MapMarker[] = [];
  const unplaced: T[] = [];
  for (const event of events) {
    const point = eventMapPoint(event);
    if (!point) {
      unplaced.push(event);
      continue;
    }
    markers.push({
      id: event.id,
      title: event.title,
      whenLabel: whenLabel(event),
      city: eventMapCity(event) ?? '',
      lat: point.lat,
      lng: point.lng,
    });
  }
  return { markers, unplaced };
}

/** Events that share a city centroid become one pin. Order follows the list. */
export function groupMapMarkers(markers: readonly MapMarker[]): MapMarker[][] {
  const groups: MapMarker[][] = [];
  const index = new Map<string, number>();
  for (const marker of markers) {
    const key = `${marker.lat.toFixed(4)},${marker.lng.toFixed(4)}`;
    const at = index.get(key);
    if (at == null) {
      index.set(key, groups.length);
      groups.push([marker]);
    } else {
      groups[at].push(marker);
    }
  }
  return groups;
}

function hostAllowed(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return LINK_SUFFIXES.some((suffix) => host === suffix || host.endsWith(`.${suffix}`));
}

/** https link on an attribution host. Anything else stays inside the map. */
export function safeMapLink(url: string): string | null {
  try {
    const u = new URL(url);
    if (u.protocol !== 'https:' || u.username || u.password || u.port) return null;
    if (!hostAllowed(u.hostname)) return null;
    return u.toString();
  } catch {
    return null;
  }
}

/** Message posted by the map page. Unknown shapes are ignored. */
export function readMapMessage(data: unknown): MapMessage | null {
  let value: unknown = data;
  if (typeof data === 'string') {
    try { value = JSON.parse(data); } catch { return null; }
  }
  if (!value || typeof value !== 'object') return null;
  const msg = value as { type?: unknown; id?: unknown; url?: unknown };
  if (msg.type === 'lock' || msg.type === 'unlock' || msg.type === 'error') return { type: msg.type };
  if (msg.type === 'open' && typeof msg.id === 'string' && msg.id.length > 0 && msg.id.length <= 80) {
    return { type: 'open', id: msg.id };
  }
  if (msg.type === 'link' && typeof msg.url === 'string') {
    const url = safeMapLink(msg.url);
    return url ? { type: 'link', url } : null;
  }
  return null;
}

export function dispatchMapMessage(
  data: unknown,
  ids: ReadonlySet<string>,
  handlers: {
    onOpen: (id: string) => void;
    onLink: (url: string) => void;
    onLock: (locked: boolean) => void;
    onError: () => void;
  },
): void {
  const msg = readMapMessage(data);
  if (!msg) return;
  if (msg.type === 'open') {
    if (ids.has(msg.id)) handlers.onOpen(msg.id);
    return;
  }
  if (msg.type === 'link') {
    handlers.onLink(msg.url);
    return;
  }
  if (msg.type === 'lock') handlers.onLock(true);
  else if (msg.type === 'unlock') handlers.onLock(false);
  else if (msg.type === 'error') handlers.onError();
}
