// Named list views for the Events screen.
// One menu picks the view. Sort stays soonest. Archived rows stay out
// (eventsInRange). Near me and the format views reuse the existing filters.

import {
  EVENT_FORMATS, eventFormatLabel, filterEventsForList,
  type EventFormat, type EventFormatInput, type GeoPoint,
} from './event-filters';
import {
  classifyEventRelation, eventsInRange,
  type EventRelation, type EventRelationContext, type EventTimeRange,
} from './event-relation';

export const EVENT_VIEW_IDS = ['mine', 'upcoming', 'past', 'online', 'in_person', 'hybrid', 'near', 'map'] as const;
export type EventViewId = (typeof EVENT_VIEW_IDS)[number];

export const EVENT_VIEWS: { id: EventViewId; label: string }[] = [
  { id: 'mine', label: 'My Upcoming Events' },
  { id: 'upcoming', label: 'All Upcoming Events' },
  { id: 'past', label: 'Past Events' },
  { id: 'online', label: eventFormatLabel('online') },
  { id: 'in_person', label: eventFormatLabel('in_person') },
  { id: 'hybrid', label: eventFormatLabel('hybrid') },
  { id: 'near', label: 'Near Me' },
  { id: 'map', label: 'Map' },
];

export function eventViewLabel(id: EventViewId): string {
  return EVENT_VIEWS.find((view) => view.id === id)?.label ?? 'My Upcoming Events';
}

const ALL_FORMATS = new Set<EventFormat>(EVENT_FORMATS);

export type EventViewSpec = {
  range: EventTimeRange;
  /** Hosting or going, upcoming only. */
  mine: boolean;
  format: EventFormat | null;
  near: boolean;
  /** Same rows as All Upcoming, drawn on the map. */
  map: boolean;
};

export function eventViewSpec(id: EventViewId): EventViewSpec {
  switch (id) {
    case 'mine': return { range: 'upcoming', mine: true, format: null, near: false, map: false };
    case 'past': return { range: 'past', mine: false, format: null, near: false, map: false };
    case 'online':
    case 'in_person':
    case 'hybrid':
      return { range: 'upcoming', mine: false, format: id, near: false, map: false };
    case 'near': return { range: 'upcoming', mine: false, format: null, near: true, map: false };
    case 'map': return { range: 'upcoming', mine: false, format: null, near: false, map: true };
    case 'upcoming': return { range: 'upcoming', mine: false, format: null, near: false, map: false };
  }
}

type ViewEvent = EventFormatInput & {
  id: string;
  title: string;
  description: string;
  venue_name?: string | null;
  starts_at: string;
  ends_at: string | null;
  archived: boolean;
  created_by?: string | null;
  /** Current owner. Counts as hosting on this list, with created_by. */
  owner_id?: string | null;
  meetup_id?: string | null;
};

/** Rows for the active view, soonest first. A null near point does not filter. */
export function eventsForView<T extends ViewEvent>(
  events: readonly T[],
  opts: {
    view: EventViewId;
    query: string;
    now: number;
    relation: EventRelationContext;
    near: { origin: GeoPoint; radiusMiles: number } | null;
  },
): T[] {
  const spec = eventViewSpec(opts.view);
  const ranged = eventsInRange(events, { range: spec.range, sort: 'soonest', query: opts.query, now: opts.now });
  const formats = spec.format ? new Set<EventFormat>([spec.format]) : ALL_FORMATS;
  const filtered = filterEventsForList(ranged, { formats, near: spec.near ? opts.near : null });
  if (!spec.mine) return filtered;
  return filtered.filter((event) => {
    const relation = classifyEventRelation(event, opts.relation);
    return relation === 'hosting' || relation === 'attending';
  });
}

/** Small card label. Hosting wins over Going. Other events get no badge. */
export function memberEventBadge(relation: EventRelation): 'Hosting' | 'Going' | null {
  if (relation === 'hosting') return 'Hosting';
  if (relation === 'attending') return 'Going';
  return null;
}

/** Sync is moderator-only. New event uses the same moderator gate as the manage screen. */
export function eventScreenActions(mod: boolean): Array<'sync' | 'new'> {
  return mod ? ['sync', 'new'] : [];
}
