// Club event list filters: format (online / in person / hybrid) and Near me.
// List rows do not include a street or exact coordinates. Near me uses the
// city centroid for venue_locality when we have one. It does not geocode a street.
// Online events stay in the list when Near me is on. In person and hybrid events
// with no known city are left out, because their distance is unknown.

import { isOnlinePlace, publicLocality } from './place';

export const EVENT_FORMATS = ['online', 'in_person', 'hybrid'] as const;
export type EventFormat = (typeof EVENT_FORMATS)[number];

export const NEAR_RADII = [5, 10, 25, 50] as const;
export type NearRadius = (typeof NEAR_RADII)[number];
export const DEFAULT_NEAR_RADIUS: NearRadius = 10;

export type GeoPoint = { lat: number; lng: number };

export type EventFormatInput = {
  venue_name?: string | null;
  venue_address?: string | null;
  venue_locality?: string | null;
  online_meeting_url?: string | null;
  /** Set by the database. Null means the place is still unknown. Absent on an unmigrated list. */
  place_kind?: EventFormat | null;
};

const FORMAT_LABEL: Record<EventFormat, string> = {
  online: 'Online',
  in_person: 'In person',
  hybrid: 'Hybrid',
};

export function eventFormatLabel(format: EventFormat): string {
  return FORMAT_LABEL[format];
}

export function allFormatsSelected(selected: ReadonlySet<EventFormat>): boolean {
  return EVENT_FORMATS.every((format) => selected.has(format));
}

/**
 * Online, in person, or hybrid.
 * place_kind wins when the row has it. A legacy row (no place_kind) is classified
 * from the venue name, the city, and a join URL when that URL is actually on the row.
 * List rows omit the join URL, so hybrid on the list depends on place_kind.
 */
export function classifyEventFormat(event: EventFormatInput): EventFormat | null {
  if (event.place_kind === 'online' || event.place_kind === 'in_person' || event.place_kind === 'hybrid') {
    return event.place_kind;
  }
  if (event.place_kind === null) return null;
  const name = event.venue_name ?? null;
  const address = event.venue_address ?? null;
  const locality = event.venue_locality ?? null;
  const link = typeof event.online_meeting_url === 'string' && event.online_meeting_url.trim() !== '';
  if (isOnlinePlace(name, address) || isOnlinePlace(name, null)) return 'online';
  const physical = Boolean(
    (name && name.trim() && !isOnlinePlace(name, null))
    || (locality && locality.trim() && !isOnlinePlace(null, locality))
    || (address && address.trim() && !isOnlinePlace(null, address)),
  );
  if (physical && link) return 'hybrid';
  if (link) return 'online';
  if (physical) return 'in_person';
  return null;
}

/** Every format selected does not narrow the list, so an unknown place stays visible. */
export function eventMatchesFormats(event: EventFormatInput, selected: ReadonlySet<EventFormat>): boolean {
  if (allFormatsSelected(selected)) return true;
  const format = classifyEventFormat(event);
  return format != null && selected.has(format);
}

