const CITY_ALIAS: Record<string, string> = {
  nyc: 'new york, ny',
  'new york': 'new york, ny',
  'new york city': 'new york, ny',
  manhattan: 'manhattan, ny',
  brooklyn: 'brooklyn, ny',
  queens: 'queens, ny',
  bronx: 'bronx, ny',
  'the bronx': 'bronx, ny',
  'staten island': 'staten island, ny',
  'jersey city': 'jersey city, nj',
  hoboken: 'hoboken, nj',
  newark: 'newark, nj',
  boston: 'boston, ma',
  philadelphia: 'philadelphia, pa',
};

function normalizeLocality(raw?: string | null): string | null {
  if (!raw) return null;
  let s = raw.trim().toLowerCase().replace(/\./g, '').replace(/\s+/g, ' ');
  s = s.replace(/, (usa|us|united states)$/g, '');
  s = s.replace(/(?:,)?\s+\d{5}(?:-\d{4})?$/g, '');
  s = s.replace(/,\s*$/g, '').trim();
  if (!s) return null;
  if (!s.includes(',')) return CITY_ALIAS[s] ?? null;
  return s;
}

/** City centroid for a locality such as "Brooklyn, NY". Null when the city is not in the table. */
export function cityCentroid(locality?: string | null): GeoPoint | null {
  const key = normalizeLocality(locality);
  if (!key) return null;
  return CENTROIDS[key] ?? null;
}

/** Point used for Near me. City only. A street is not turned into a pin. */
export function eventDistancePoint(event: { venue_locality?: string | null; venue_address?: string | null }): GeoPoint | null {
  return cityCentroid(event.venue_locality) ?? cityCentroid(publicLocality(event.venue_address));
}

export function haversineMiles(a: GeoPoint, b: GeoPoint): number {
  const earth = 3958.7613;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const lat1 = (a.lat * Math.PI) / 180;
  const lat2 = (b.lat * Math.PI) / 180;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 2 * earth * Math.asin(Math.min(1, Math.sqrt(h)));
}

/**
 * Online events match at any distance. In person and hybrid events match when
 * their city centroid is within the radius. No city means not near.
 */
export function eventMatchesNearMe(event: EventFormatInput, origin: GeoPoint, radiusMiles: number): boolean {
  if (!(radiusMiles > 0)) return false;
  if (classifyEventFormat(event) === 'online') return true;
  const point = eventDistancePoint(event);
  if (!point) return false;
  return haversineMiles(origin, point) <= radiusMiles;
}

export function filterEventsForList<T extends EventFormatInput>(
  events: readonly T[],
  opts: { formats: ReadonlySet<EventFormat>; near: { origin: GeoPoint; radiusMiles: number } | null },
): T[] {
  return events.filter((event) => {
    if (!eventMatchesFormats(event, opts.formats)) return false;
    if (opts.near && !eventMatchesNearMe(event, opts.near.origin, opts.near.radiusMiles)) return false;
    return true;
  });
}
