// Same OpenFreeMap page as iOS and Android, in an iframe. No Google Maps JavaScript.
// A srcdoc frame's location.origin is the string "null", while MapLibre's worker
// blob is created in this page's origin. MapLibre drops those worker messages, so
// the canvas stays the empty background color: zoom controls, no tiles, no pins.
// A blob: document shares this page's origin, so the worker is accepted.
import { createElement, useEffect, useMemo, useRef, useState } from 'react';
import { Linking, Text, View } from 'react-native';
import { styles } from './ui';
import { buildEventMapHtml } from '../lib/event-map-html';
import { dispatchMapMessage, type MapMarker } from '../lib/event-map';
import { colors, fs, radius } from '../lib/theme';

const FAILED = 'The map could not load. Use the list.';

export function EventMap({ markers, height, onOpen, onLock }: {
  markers: readonly MapMarker[];
  height: number;
  onOpen: (id: string) => void;
  onLock?: (locked: boolean) => void;
}) {
  const [failed, setFailed] = useState(false);
  const html = useMemo(() => buildEventMapHtml(markers), [markers]);
  const ids = useMemo(() => new Set(markers.map((marker) => marker.id)), [markers]);
  const frameRef = useRef<HTMLIFrameElement | null>(null);
  const [frameUrl, setFrameUrl] = useState<string | null>(null);
  useEffect(() => { setFailed(false); }, [html]);
  useEffect(() => {
    const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
    setFrameUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [html]);
  useEffect(() => {
    const unlock = () => onLock?.(false);
    window.addEventListener('pointerup', unlock);
    window.addEventListener('pointercancel', unlock);
    return () => {
      window.removeEventListener('pointerup', unlock);
      window.removeEventListener('pointercancel', unlock);
    };
  }, [onLock]);
  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      if (event.source !== frameRef.current?.contentWindow) return;
      if (event.origin !== window.location.origin) return;
      dispatchMapMessage(event.data, ids, {
        onOpen,
        onLink: (url) => { Linking.openURL(url).catch(() => {}); },
        onLock: (locked) => onLock?.(locked),
        onError: () => setFailed(true),
      });
    };
    window.addEventListener('message', onMessage);
    return () => window.removeEventListener('message', onMessage);
  }, [ids, onOpen, onLock]);
  return (
    <View style={{ height, borderRadius: radius, overflow: 'hidden', borderWidth: 1, borderColor: colors.line, backgroundColor: '#e8e4dc' }}>
      {failed ? (
        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', padding: 16 }}>
          <Text style={[styles.muted, { fontSize: fs(13), textAlign: 'center' }]}>{FAILED}</Text>
        </View>
      ) : frameUrl ? createElement('iframe', {
        ref: frameRef,
        title: 'Club events map',
        src: frameUrl,
        style: { border: '0', width: '100%', height: '100%', backgroundColor: '#e8e4dc' },
      }) : null}
    </View>
  );
}
